input.command:
sed -n '69p' pr/head/.claude/hooks/session-start/loa-decisions-surface.sh | od -c | head -20; echo ----; grep -n 'Status' pr/head/.claude/skills/discovering-requirements/resources/templates/prd-template.md | head -5; echo ----; mkdir -p /tmp/rv/b && cat > /tmp/rv/b/t.bats <<'EOF'
empty_ledger(){ { sed '/^schema_version:/,$d' "$1"; printf 'schema_version: 1\ndecisions: []\n'; } > "$2"; }
setup() { empty_ledger /nonexistent/decisions.yaml "$BATS_TEST_TMPDIR/x.yaml"; }
@test "setup survives missing ledger" { cat "$BATS_TEST_TMPDIR/x.yaml"; }
EOF
bats /tmp/rv/b/t.bats; echo "bats exit=$?"

set -e; R=/tmp/rv/repo; rm -rf $R; mkdir -p $R; cp -a /workspace/pr/head/. $R/; 
for f in scripts/compat-lib.sh scripts/pii-filter.sh scripts/lib/context-isolation-lib.sh scripts/loa-learnings-index.sh scripts/path-lib.sh scripts/bash-version-guard.sh scripts/lib/profile-lib.sh hooks/hook-guard.sh; do mkdir -p $R/.claude/$(dirname $f); [ -f $R/.claude/$f ] || cp /workspace/.claude/$f $R/.claude/$f; done
mkdir -p $R/grimoires/loa; printf '# grimoires/loa/decisions.yaml: the decision ledger (written only by dec-write-lib.sh)\nschema_version: 1\ndecisions: []\n' > $R/grimoires/loa/decisions.yaml
cd $R && git init -q && git add -A >/dev/null 2>&1 && git -c user.email=t@t -c user.name=t commit -qm base && git branch -M main && git remote add origin . ; 
ls $R/tests/unit/; command -v python3 flock; echo built

